import re
t=open('assets/prompt-templates.md').read()
lines=t.splitlines()
body=[]
for i,l in enumerate(lines,1):
    if 514<=i<=543: continue
    body.append((i,l))
toks={}
for i,l in body:
    for m in re.finditer(r'\[([a-z0-9][a-z0-9 _./-]*?)\]', l):
        toks.setdefault(m.group(1),[]).append(i)
table=set()
for i in range(518,544):
    m=re.match(r"\|\s*`\[([^\]]+)\]`", lines[i-1])
    if m: table.add(m.group(1))
print("table:",len(table))
missing={k:v for k,v in toks.items() if k not in table}
for k,v in sorted(missing.items()):
    print("MISSING?",repr(k),v[:6])
EOF

